// Fisher-Yates shuffle (returns a new array)
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Shuffle the 4 options of a question and recompute correctIndex
function shuffleOptions(q) {
  const correctVal = q.options[q.correctIndex];
  const opts = shuffle(q.options);
  return { ...q, options: opts, correctIndex: opts.indexOf(correctVal) };
}

export const PER_COMPANY = 8;
export const COMPANY_KEYS = ["ANZ", "Star", "Santos", "RioTinto", "WiseTech"];

// Assemble a fresh randomised session: PER_COMPANY random questions from each
// company's pool, options shuffled, then the whole deck shuffled.
export function buildSession(perCompany = PER_COMPANY) {
  const byCompany = {};
  COMPANY_KEYS.forEach((k) => (byCompany[k] = []));
  QUESTION_BANK.forEach((q) => byCompany[q.company]?.push(q));
  const session = [];
  COMPANY_KEYS.forEach((k) => {
    shuffle(byCompany[k]).slice(0, perCompany).forEach((q) => session.push(shuffleOptions(q)));
  });
  return shuffle(session);
}
